admin_create_po:
CREATE OR REPLACE FUNCTION public.admin_create_po(p_vendor_id uuid, p_warehouse_id uuid, p_items jsonb)
 RETURNS procurement_orders
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_po public.procurement_orders;
    v_total_cost DECIMAL(12,2) := 0;
    item RECORD;
    v_product_id UUID;
    v_qty INTEGER;
    v_cost DECIMAL(12,2);
BEGIN
    IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = auth.uid() AND role = 'admin') THEN
        RAISE EXCEPTION 'Unauthorized: Only admins can create procurement orders';
    END IF;

    IF NOT EXISTS (SELECT 1 FROM public.vendors WHERE id = p_vendor_id) THEN
        RAISE EXCEPTION 'Invalid vendor';
    END IF;

    IF NOT EXISTS (SELECT 1 FROM public.warehouses WHERE id = p_warehouse_id) THEN
        RAISE EXCEPTION 'Invalid warehouse';
    END IF;

    IF jsonb_array_length(p_items) = 0 THEN
        RAISE EXCEPTION 'Procurement order must have at least one item';
    END IF;

    -- Calculate total cost and validate items
    FOR item IN SELECT * FROM jsonb_array_elements(p_items)
    LOOP
        v_product_id := (item.value->>'product_id')::UUID;
        v_qty := (item.value->>'quantity')::INTEGER;
        v_cost := (item.value->>'cost_per_unit')::DECIMAL(12,2);

        IF NOT EXISTS (SELECT 1 FROM public.products WHERE id = v_product_id) THEN
            RAISE EXCEPTION 'Invalid product in order: %', v_product_id;
        END IF;

        IF v_qty <= 0 THEN
            RAISE EXCEPTION 'Quantity must be positive';
        END IF;

        IF v_cost < 0 THEN
            RAISE EXCEPTION 'Unit cost cannot be negative';
        END IF;

        -- NEW VALIDATION: Check if product is explicitly mapped to vendor
        IF NOT EXISTS (
            SELECT 1 FROM public.vendor_products vp
            WHERE vp.vendor_id = p_vendor_id 
              AND vp.product_id = v_product_id
              AND vp.is_active = true
        ) THEN
            RAISE EXCEPTION 'Product % is not mapped to vendor %', v_product_id, p_vendor_id;
        END IF;

        v_total_cost := v_total_cost + (v_qty * v_cost);
    END LOOP;

    -- Create PO (Restored original columns)
    INSERT INTO public.procurement_orders (vendor_id, warehouse_id, status, total_cost)
    VALUES (p_vendor_id, p_warehouse_id, 'pending', v_total_cost)
    RETURNING * INTO v_po;

    -- Insert items
    FOR item IN SELECT * FROM jsonb_array_elements(p_items)
    LOOP
        v_product_id := (item.value->>'product_id')::UUID;
        v_qty := (item.value->>'quantity')::INTEGER;
        v_cost := (item.value->>'cost_per_unit')::DECIMAL(12,2);

        -- Insert with upsert behavior to normalize duplicates from frontend array
        INSERT INTO public.procurement_order_items (procurement_order_id, product_id, quantity, cost_per_unit)
        VALUES (v_po.id, v_product_id, v_qty, v_cost)
        ON CONFLICT (procurement_order_id, product_id)
        DO UPDATE SET quantity = public.procurement_order_items.quantity + EXCLUDED.quantity;
    END LOOP;

    -- Standard audit logging using previously working 6-arg signature
    PERFORM public.write_admin_audit_log(
        'PO_CREATED', 'procurement_orders', (v_po.id)::text, p_warehouse_id, NULL,
        jsonb_build_object('vendor_id', p_vendor_id, 'total', v_total_cost, 'items', p_items)
    );

    RETURN v_po;
END;
$function$

admin_update_po_status:
CREATE OR REPLACE FUNCTION public.admin_update_po_status(p_po_id uuid, p_new_status text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_old_status TEXT;
    v_wh_id UUID;
BEGIN
    IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = auth.uid() AND role = 'admin') THEN
        RAISE EXCEPTION 'Unauthorized: Only admins can update PO status';
    END IF;

    IF p_new_status NOT IN ('approved', 'cancelled') THEN
        RAISE EXCEPTION 'Invalid status transition: %', p_new_status;
    END IF;

    SELECT status, warehouse_id INTO v_old_status, v_wh_id FROM public.procurement_orders WHERE id = p_po_id FOR UPDATE;

    IF v_old_status IS NULL THEN
        RAISE EXCEPTION 'PO not found';
    END IF;

    IF v_old_status = 'delivered' THEN
        RAISE EXCEPTION 'Cannot modify a delivered PO';
    END IF;

    IF v_old_status = 'cancelled' THEN
        RAISE EXCEPTION 'Cannot modify a cancelled PO';
    END IF;

    IF p_new_status = 'approved' AND v_old_status != 'pending' THEN
        RAISE EXCEPTION 'Only pending POs can be approved';
    END IF;

    UPDATE public.procurement_orders SET status = p_new_status WHERE id = p_po_id;

    PERFORM public.write_admin_audit_log(
        'PO_STATUS_CHANGED', 'procurement_orders', p_po_id::text, v_wh_id,
        jsonb_build_object('status', v_old_status), jsonb_build_object('status', p_new_status)
    );

    RETURN TRUE;
END;
$function$

receive_procurement_order:
CREATE OR REPLACE FUNCTION public.receive_procurement_order(p_procurement_id uuid, p_warehouse_id uuid, p_user_id uuid, p_receipt_number text, p_notes text, p_items jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_order RECORD;
    v_user_role TEXT;
    v_user_warehouse UUID;
    v_user_suspended BOOLEAN;
    v_item JSONB;
    v_po_item RECORD;
    v_receipt_id UUID;
    v_grn_item_id UUID;
    v_batch_id UUID;
    v_total_accepted INTEGER;
    v_all_received BOOLEAN := TRUE;
    v_any_received BOOLEAN := FALSE;
    v_status TEXT;
BEGIN
    -- 1. Check idempotency
    SELECT id INTO v_receipt_id FROM public.goods_receipts WHERE receipt_number = p_receipt_number;
    IF FOUND THEN
        RETURN jsonb_build_object('success', true, 'message', 'Receipt already processed (idempotent)', 'receipt_id', v_receipt_id);
    END IF;

    -- 2. Validate Caller
    SELECT role, warehouse_id, is_suspended INTO v_user_role, v_user_warehouse, v_user_suspended
    FROM public.profiles WHERE id = p_user_id;

    IF v_user_suspended = TRUE THEN RAISE EXCEPTION 'Unauthorized: Account is suspended'; END IF;
    IF v_user_role NOT IN ('admin', 'warehouse_manager', 'warehouse_staff') THEN RAISE EXCEPTION 'Unauthorized: Invalid role'; END IF;

    -- 3. Lock PO
    SELECT * INTO v_order FROM public.procurement_orders WHERE id = p_procurement_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Procurement order not found'; END IF;
    IF v_order.status IN ('received', 'cancelled') THEN RAISE EXCEPTION 'Cannot receive a PO that is %', v_order.status; END IF;
    IF v_order.warehouse_id != p_warehouse_id THEN RAISE EXCEPTION 'Warehouse mismatch on PO'; END IF;

    -- 4. Cross-warehouse validation
    IF v_user_role != 'admin' AND v_user_warehouse != p_warehouse_id THEN
        RAISE EXCEPTION 'Unauthorized: Cross-warehouse receiving blocked';
    END IF;

    -- 5. Create GRN
    INSERT INTO public.goods_receipts (receipt_number, procurement_order_id, vendor_id, warehouse_id, received_by, notes)
    VALUES (p_receipt_number, p_procurement_id, v_order.vendor_id, p_warehouse_id, p_user_id, p_notes)
    RETURNING id INTO v_receipt_id;

    -- 6. Process items
    FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
    LOOP
        IF (v_item->>'accepted_quantity')::INTEGER < 0 OR (v_item->>'rejected_quantity')::INTEGER < 0 THEN
            RAISE EXCEPTION 'Negative quantities not allowed';
        END IF;

        IF (v_item->>'accepted_quantity')::INTEGER = 0 AND (v_item->>'rejected_quantity')::INTEGER = 0 THEN
            CONTINUE; -- Skip empty lines
        END IF;

        -- Lock PO Item
        SELECT * INTO v_po_item FROM public.procurement_order_items 
        WHERE id = (v_item->>'procurement_order_item_id')::UUID 
          AND procurement_order_id = p_procurement_id FOR UPDATE;

        IF NOT FOUND THEN RAISE EXCEPTION 'PO Item % not found', v_item->>'procurement_order_item_id'; END IF;

        IF v_po_item.received_quantity + (v_item->>'accepted_quantity')::INTEGER + (v_item->>'rejected_quantity')::INTEGER > v_po_item.quantity THEN
            RAISE EXCEPTION 'Over-receipt detected for product %', v_po_item.product_id;
        END IF;

        v_any_received := TRUE;

        -- Create GRN Item
        INSERT INTO public.goods_receipt_items (
            receipt_id, procurement_order_item_id, product_id, 
            quantity_received, accepted_quantity, rejected_quantity, 
            unit_cost, batch_number, expiry_date
        ) VALUES (
            v_receipt_id, v_po_item.id, v_po_item.product_id,
            (v_item->>'accepted_quantity')::INTEGER + (v_item->>'rejected_quantity')::INTEGER,
            (v_item->>'accepted_quantity')::INTEGER,
            (v_item->>'rejected_quantity')::INTEGER,
            (v_item->>'unit_cost')::NUMERIC,
            v_item->>'batch_number',
            (v_item->>'expiry_date')::DATE
        ) RETURNING id INTO v_grn_item_id;

        -- Update PO item
        UPDATE public.procurement_order_items
        SET received_quantity = received_quantity + (v_item->>'accepted_quantity')::INTEGER + (v_item->>'rejected_quantity')::INTEGER
        WHERE id = v_po_item.id;

        -- Accepted stock accounting
        IF (v_item->>'accepted_quantity')::INTEGER > 0 THEN
            -- 1. Create product batch with provenance
            INSERT INTO public.product_batches (
                product_id, warehouse_id, batch_number, expiry_date, 
                received_quantity, available_quantity, status, goods_receipt_item_id
            ) VALUES (
                v_po_item.product_id, p_warehouse_id, v_item->>'batch_number', (v_item->>'expiry_date')::DATE,
                (v_item->>'accepted_quantity')::INTEGER, (v_item->>'accepted_quantity')::INTEGER, 'active', v_grn_item_id
            ) RETURNING id INTO v_batch_id;

            -- 2. Increment warehouse stock
            UPDATE public.warehouse_stock
            SET quantity = quantity + (v_item->>'accepted_quantity')::INTEGER
            WHERE product_id = v_po_item.product_id AND warehouse_id = p_warehouse_id;

            -- 3. Write stock ledger
            INSERT INTO public.stock_ledgers (
                warehouse_id, product_id, batch_id, quantity_change, reason, performed_by
            ) VALUES (
                p_warehouse_id, v_po_item.product_id, v_batch_id, (v_item->>'accepted_quantity')::INTEGER, 'grn', p_user_id
            );

            -- Add to putaway tasks
            INSERT INTO public.putaway_tasks (warehouse_id, product_id, batch_id, quantity, source_type)
            VALUES (p_warehouse_id, v_po_item.product_id, v_batch_id, (v_item->>'accepted_quantity')::INTEGER, 'grn');
        END IF;
    END LOOP;

    IF NOT v_any_received THEN
        RAISE EXCEPTION 'No items received';
    END IF;

    -- Evaluate PO Status
    SELECT bool_and(received_quantity >= quantity) INTO v_all_received
    FROM public.procurement_order_items WHERE procurement_order_id = p_procurement_id;

    IF v_all_received THEN
        v_status := 'received';
    ELSE
        v_status := 'partially_received';
    END IF;

    UPDATE public.procurement_orders SET status = v_status WHERE id = p_procurement_id;

    RETURN jsonb_build_object('success', true, 'receipt_id', v_receipt_id, 'new_status', v_status);
END;
$function$

approve_staff_role:
CREATE OR REPLACE FUNCTION public.approve_staff_role(p_user_id uuid, p_role user_role, p_clean_name text, p_warehouse_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_existing_emp_id TEXT;
    v_target RECORD;
BEGIN
    -- Verify caller is admin
    IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = auth.uid() AND role = 'admin') THEN
        RAISE EXCEPTION 'Unauthorized';
    END IF;

    IF p_user_id = auth.uid() THEN
        RAISE EXCEPTION 'Cannot approve self';
    END IF;

    -- Block Driver approval through generic path
    IF p_role = 'driver' THEN
        RAISE EXCEPTION 'Driver approval must use dedicated driver verification flow. Use approve_driver_application instead.';
    END IF;

    IF p_role NOT IN ('picker', 'warehouse_staff') THEN
        RAISE EXCEPTION 'Invalid role for generic staff approval';
    END IF;

    IF p_warehouse_id IS NOT NULL THEN
        IF NOT EXISTS (SELECT 1 FROM public.warehouses WHERE id = p_warehouse_id AND is_active = true) THEN
            RAISE EXCEPTION 'Invalid or inactive warehouse selected';
        END IF;
    END IF;

    SELECT role, employee_id INTO v_target FROM public.profiles WHERE id = p_user_id FOR UPDATE;

    v_existing_emp_id := v_target.employee_id;

    IF v_existing_emp_id IS NULL THEN
        v_existing_emp_id := 'EMP-' || nextval('public.staff_emp_seq');
    END IF;

    UPDATE public.profiles 
    SET role = p_role, 
        full_name = p_clean_name,
        employee_id = v_existing_emp_id,
        is_pending_staff = FALSE,
        requested_role = NULL,
        warehouse_id = p_warehouse_id
    WHERE id = p_user_id;

    PERFORM public.write_admin_audit_log(
        'STAFF_APPROVED', 'profiles', p_user_id::text, NULL,
        jsonb_build_object('role', v_target.role),
        jsonb_build_object('role', p_role, 'warehouse_id', p_warehouse_id, 'employee_id', v_existing_emp_id), NULL
    );
END;
$function$

admin_update_staff_role:
CREATE OR REPLACE FUNCTION public.admin_update_staff_role(p_target_id uuid, p_role user_role)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_old_role TEXT;
BEGIN
    IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = auth.uid() AND role = 'admin') THEN
        RAISE EXCEPTION 'Unauthorized';
    END IF;

    IF p_role NOT IN ('picker', 'driver', 'warehouse_staff') THEN
        RAISE EXCEPTION 'Cannot assign non-operational role via this workflow';
    END IF;

    SELECT role INTO v_old_role FROM public.profiles WHERE id = p_target_id FOR UPDATE;

    IF v_old_role NOT IN ('picker', 'driver', 'warehouse_staff') THEN
        RAISE EXCEPTION 'Target is not a valid staff member';
    END IF;

    -- Check for active work that prevents role change
    IF v_old_role = 'driver' THEN
        IF EXISTS (SELECT 1 FROM public.logistics_trips WHERE driver_id = p_target_id AND status IN ('accepted', 'in_transit')) THEN
            RAISE EXCEPTION 'Cannot change role: Driver has active trips';
        END IF;
    END IF;

    -- Validate active work for Pickers: assigned ('placed') or currently 'picking' through 'staged'
    IF v_old_role IN ('picker', 'warehouse_staff') THEN
        IF EXISTS (SELECT 1 FROM public.orders WHERE picker_id = p_target_id AND status IN ('placed', 'picking', 'waiting_for_packing', 'packing', 'packed', 'staged')) THEN
            RAISE EXCEPTION 'Cannot change role: Worker has active unfinished work';
        END IF;
    END IF;

    UPDATE public.profiles SET role = p_role WHERE id = p_target_id;

    PERFORM public.write_admin_audit_log(
        'STAFF_ROLE_CHANGED', 'profiles', p_target_id::text, NULL,
        jsonb_build_object('role', v_old_role), jsonb_build_object('role', p_role), NULL
    );

    RETURN TRUE;
END;
$function$

admin_update_staff_warehouse:
CREATE OR REPLACE FUNCTION public.admin_update_staff_warehouse(p_target_id uuid, p_warehouse_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_role TEXT;
BEGIN
    IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = auth.uid() AND role = 'admin') THEN
        RAISE EXCEPTION 'Unauthorized';
    END IF;

    SELECT role INTO v_role FROM public.profiles WHERE id = p_target_id FOR UPDATE;

    IF v_role NOT IN ('picker', 'driver', 'warehouse_staff') THEN
        RAISE EXCEPTION 'Target is not a valid staff member';
    END IF;

    -- Validate active work for Pickers: assigned ('placed') or currently 'picking' through 'staged'
    IF v_role IN ('picker', 'warehouse_staff') THEN
        IF EXISTS (SELECT 1 FROM public.orders WHERE picker_id = p_target_id AND status IN ('placed', 'picking', 'waiting_for_packing', 'packing', 'packed', 'staged')) THEN
            RAISE EXCEPTION 'Cannot reassign warehouse: Worker has active unfinished work';
        END IF;
    END IF;

    IF v_role = 'driver' THEN
        IF EXISTS (SELECT 1 FROM public.logistics_trips WHERE driver_id = p_target_id AND status IN ('accepted', 'in_transit')) THEN
            RAISE EXCEPTION 'Cannot reassign warehouse: Driver has active trips';
        END IF;
    END IF;

    UPDATE public.profiles SET warehouse_id = p_warehouse_id WHERE id = p_target_id;

    PERFORM public.write_admin_audit_log(
        'STAFF_WAREHOUSE_CHANGED', 'profiles', p_target_id::text, NULL,
        NULL, jsonb_build_object('warehouse_id', p_warehouse_id), NULL
    );

    RETURN TRUE;
END;
$function$
